components.css:
.ds-purpose-ledger { max-width: 56rem; color: var(--color-text); font-family: var(--font-sans); line-height: 1.5; }
.ds-sphere-group { margin: 0; padding: 0; list-style: none; overflow: hidden; border-radius: 8px; background: var(--color-surface); }
.ds-sphere-group li + li { border-top: 1px solid var(--color-border); }
.ds-sphere-link { display: grid; grid-template-columns: minmax(0,1fr) auto 1rem; min-height: 64px; box-sizing: border-box; align-items: center; gap: 12px; padding: 12px 16px; color: var(--color-text); text-decoration: none; transition: background-color 150ms; }
.ds-sphere-name { min-width: 0; overflow-wrap: anywhere; font-size: 16px; font-weight: 500; }
.ds-total { color: var(--color-text); text-align: right; font-family: var(--font-mono); font-size: 14px; line-height: 20px; font-weight: 400; font-variant-numeric: tabular-nums; }
.ds-total-value { display: inline-flex; align-items: center; gap: 4px; }
.ds-chevron { width: 16px; height: 16px; flex-shrink: 0; color: var(--color-text-muted); }
.ds-group-heading { margin: 24px 0 12px; font-size: 16px; font-weight: 600; }
.ds-archive-link { display: flex; align-items: center; justify-content: space-between; gap: 12px; min-height: 44px; box-sizing: border-box; margin-top: 24px; padding: 12px 16px; border-radius: 8px; background: var(--color-surface); color: var(--color-text); text-decoration: none; transition: background-color 150ms; }
.ds-support { margin-top: 4px; }
.ds-support-summary { display: flex; min-height: 44px; box-sizing: border-box; align-items: center; justify-content: space-between; gap: 12px; padding: 8px 12px; border-radius: 8px; color: var(--color-text-muted); font-size: 14px; list-style: none; cursor: pointer; transition: background-color 150ms, color 150ms; }
.ds-support-summary::-webkit-details-marker { display: none; }
.ds-support[open] > .ds-support-summary > .ds-chevron { rotate: 180deg; }
.ds-sphere-link:hover, .ds-archive-link:hover, .ds-support-summary:hover { background: var(--color-surface-hover); color: var(--color-text); }
.ds-sphere-link:active, .ds-archive-link:active, .ds-support-summary:active { background: var(--color-surface-active); }
.ds-sphere-link:focus-visible { outline: 2px solid var(--color-accent); outline-offset: -2px; }
.ds-archive-link:focus-visible, .ds-support-summary:focus-visible { outline: 2px solid var(--color-accent); outline-offset: 2px; }
.ds-support p { max-width: 65ch; color: var(--color-text-muted); font-size: 14px; }
.ds-warning { color: var(--color-warning); }
.ds-warning-icon { width: 16px; height: 16px; flex-shrink: 0; }
.ds-warning-copy { display: block; font-family: var(--font-sans); font-size: 12px; line-height: 16px; }
.ds-sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@media (prefers-reduced-motion: reduce) { .ds-sphere-link, .ds-archive-link, .ds-support-summary { transition: none; } }
